-- Original schema 13; source commit 50668c0884040a7c7e475af6ef94559ccb7816cd.
-- Exported using original Table definitions and original generated metadata.
CREATE TABLE "app_settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "checkout_drafts" ("id" TEXT NOT NULL, "kind" TEXT NOT NULL, "label" TEXT NOT NULL, "state" TEXT NOT NULL DEFAULT 'editing', "payload" TEXT NOT NULL, "revision" INTEGER NOT NULL DEFAULT 1, "operation_key" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "customers" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "phone" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "expenses" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "description" TEXT NOT NULL, "amount_minor" INTEGER NOT NULL, "method" TEXT NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "financial_correction_reversals" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "correction_id" INTEGER NOT NULL UNIQUE REFERENCES financial_corrections (id), "reason" TEXT NOT NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "financial_corrections" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "target" TEXT NOT NULL, "delta_minor" INTEGER NOT NULL, "reason" TEXT NOT NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "installment_payments" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "plan_id" INTEGER NOT NULL REFERENCES installment_plans (id), "amount_minor" INTEGER NOT NULL, "due_date" INTEGER NOT NULL, "paid_at" INTEGER NULL, "status" TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE "installment_plans" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "owner_type" TEXT NOT NULL, "owner_id" INTEGER NOT NULL, "party_type" TEXT NOT NULL, "party_id" INTEGER NOT NULL, "principal_minor" INTEGER NOT NULL, "interest_minor" INTEGER NOT NULL DEFAULT 0, "total_minor" INTEGER NOT NULL, "paid_minor" INTEGER NOT NULL DEFAULT 0, "installment_count" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'open', "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "inventory_adjustments" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "product_id" INTEGER NOT NULL REFERENCES products (id), "previous_qty" INTEGER NOT NULL, "counted_qty" INTEGER NOT NULL, "unit_cost_minor" INTEGER NOT NULL, "value_delta_minor" INTEGER NOT NULL, "reason" TEXT NOT NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "ledger_entries" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "reference_type" TEXT NOT NULL, "reference_id" INTEGER NOT NULL, "description" TEXT NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "ledger_lines" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "entry_id" INTEGER NOT NULL REFERENCES ledger_entries (id), "account_code" TEXT NOT NULL, "debit_minor" INTEGER NOT NULL DEFAULT 0, "credit_minor" INTEGER NOT NULL DEFAULT 0, "party_type" TEXT NULL, "party_id" INTEGER NULL);
CREATE TABLE "opening_balances" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "balance_type" TEXT NOT NULL, "party_id" INTEGER NULL, "amount_minor" INTEGER NOT NULL, "due_date" INTEGER NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "payments" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "owner_type" TEXT NOT NULL, "owner_id" INTEGER NOT NULL, "method" TEXT NOT NULL, "amount_minor" INTEGER NOT NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "products" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "barcode" TEXT NULL UNIQUE, "category" TEXT NULL, "image_path" TEXT NULL, "stock_qty" INTEGER NOT NULL DEFAULT 0, "min_stock_qty" INTEGER NOT NULL DEFAULT 1, "sale_price_minor" INTEGER NOT NULL, "avg_cost_minor" INTEGER NOT NULL DEFAULT 0, "inventory_value_minor" INTEGER NOT NULL DEFAULT 0, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NULL);
CREATE TABLE "purchase_invoices" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "invoice_no" TEXT NOT NULL UNIQUE, "supplier_id" INTEGER NULL REFERENCES suppliers (id), "shift_id" INTEGER NULL REFERENCES shifts (id), "total_minor" INTEGER NOT NULL, "paid_minor" INTEGER NOT NULL, "remaining_minor" INTEGER NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "purchase_items" ("product_name_snapshot" TEXT NOT NULL DEFAULT '', "product_barcode_snapshot" TEXT NULL, "identity_snapshot_origin" TEXT NOT NULL DEFAULT 'captured', "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "purchase_id" INTEGER NOT NULL REFERENCES purchase_invoices (id), "product_id" INTEGER NOT NULL REFERENCES products (id), "qty" INTEGER NOT NULL, "unit_cost_minor" INTEGER NOT NULL, "line_total_minor" INTEGER NOT NULL);
CREATE TABLE "purchase_return_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "return_id" INTEGER NOT NULL REFERENCES purchase_returns (id), "purchase_item_id" INTEGER NOT NULL REFERENCES purchase_items (id), "product_id" INTEGER NOT NULL REFERENCES products (id), "qty" INTEGER NOT NULL, "unit_cost_minor" INTEGER NOT NULL, "inventory_unit_cost_minor" INTEGER NOT NULL);
CREATE TABLE "purchase_returns" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "purchase_id" INTEGER NOT NULL REFERENCES purchase_invoices (id), "return_no" TEXT NOT NULL UNIQUE, "credit_minor" INTEGER NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "sale_invoices" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "invoice_no" TEXT NOT NULL UNIQUE, "customer_id" INTEGER NULL REFERENCES customers (id), "shift_id" INTEGER NULL REFERENCES shifts (id), "subtotal_minor" INTEGER NOT NULL, "discount_minor" INTEGER NOT NULL DEFAULT 0, "interest_minor" INTEGER NOT NULL DEFAULT 0, "total_minor" INTEGER NOT NULL, "paid_minor" INTEGER NOT NULL, "remaining_minor" INTEGER NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "sale_items" ("product_name_snapshot" TEXT NOT NULL DEFAULT '', "product_barcode_snapshot" TEXT NULL, "identity_snapshot_origin" TEXT NOT NULL DEFAULT 'captured', "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "sale_id" INTEGER NOT NULL REFERENCES sale_invoices (id), "product_id" INTEGER NOT NULL REFERENCES products (id), "qty" INTEGER NOT NULL, "unit_price_minor" INTEGER NOT NULL, "unit_cost_minor" INTEGER NOT NULL, "cost_minor" INTEGER NOT NULL DEFAULT 0, "line_total_minor" INTEGER NOT NULL);
CREATE TABLE "sale_return_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "return_id" INTEGER NOT NULL REFERENCES sale_returns (id), "sale_item_id" INTEGER NOT NULL REFERENCES sale_items (id), "product_id" INTEGER NOT NULL REFERENCES products (id), "qty" INTEGER NOT NULL, "unit_price_minor" INTEGER NOT NULL, "unit_cost_minor" INTEGER NOT NULL, "cost_minor" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "sale_returns" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "sale_id" INTEGER NOT NULL REFERENCES sale_invoices (id), "return_no" TEXT NOT NULL UNIQUE, "refund_minor" INTEGER NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "shifts" ("opening_ledger_entry_id" INTEGER NULL, "cash_delta_before_upgrade_minor" INTEGER NULL, "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "opened_at" INTEGER NOT NULL, "closed_at" INTEGER NULL, "opening_cash_minor" INTEGER NOT NULL, "expected_cash_minor" INTEGER NULL, "actual_cash_minor" INTEGER NULL, "difference_minor" INTEGER NULL, "status" TEXT NOT NULL DEFAULT 'open');
CREATE TABLE "stock_movements" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "product_id" INTEGER NOT NULL REFERENCES products (id), "type" TEXT NOT NULL, "qty_delta" INTEGER NOT NULL, "balance_after" INTEGER NOT NULL, "reference_type" TEXT NOT NULL, "reference_id" INTEGER NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "suppliers" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "phone" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "users" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "username" TEXT NOT NULL UNIQUE, "password_hash" TEXT NOT NULL, "full_name" TEXT NOT NULL, "must_change_password" INTEGER NOT NULL DEFAULT 1 CHECK ("must_change_password" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE INDEX idx_checkout_updated ON checkout_drafts(kind, updated_at);
CREATE INDEX idx_customers_name ON customers(name);
CREATE INDEX idx_expenses_created_at ON expenses(created_at);
CREATE INDEX idx_financial_corrections_target_created ON financial_corrections(target, created_at);
CREATE INDEX idx_installment_payments_plan_due ON installment_payments(plan_id, due_date);
CREATE INDEX idx_installment_plans_status_created ON installment_plans(status, created_at DESC);
CREATE INDEX idx_inventory_adjustments_product_created ON inventory_adjustments(product_id, created_at);
CREATE INDEX idx_ledger_entries_created_at ON ledger_entries(created_at);
CREATE INDEX idx_ledger_entries_reference ON ledger_entries(reference_type, reference_id);
CREATE INDEX idx_ledger_lines_account_code ON ledger_lines(account_code);
CREATE INDEX idx_ledger_lines_entry_id ON ledger_lines(entry_id);
CREATE INDEX idx_ledger_lines_party ON ledger_lines(party_type, party_id);
CREATE INDEX idx_opening_balances_target ON opening_balances(balance_type, party_id);
CREATE INDEX idx_payments_owner ON payments(owner_type, owner_id);
CREATE INDEX idx_products_name ON products(name);
CREATE INDEX idx_purchase_invoices_created_id ON purchase_invoices(created_at DESC, id DESC);
CREATE INDEX idx_purchase_return_items_purchase_item_id ON purchase_return_items(purchase_item_id);
CREATE INDEX idx_purchase_returns_purchase_id ON purchase_returns(purchase_id);
CREATE INDEX idx_sale_invoices_created_id ON sale_invoices(created_at DESC, id DESC);
CREATE INDEX idx_sale_items_sale_id ON sale_items(sale_id);
CREATE INDEX idx_sale_returns_created_at ON sale_returns(created_at);
CREATE INDEX idx_stock_movements_product_id ON stock_movements(product_id);
CREATE INDEX idx_stock_movements_reference ON stock_movements(reference_type, reference_id);
CREATE INDEX idx_suppliers_name ON suppliers(name);
PRAGMA user_version=13;
